namespace sv_97d11cedc5ff4667abf60161c0fe1b08.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_97d11cedc5ff4667abf60161c0fe1b08.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_97d11cedc5ff4667abf60161c0fe1b08.Components.Pages.Settings
@using sv_97d11cedc5ff4667abf60161c0fe1b08.Services

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (profile is null)
    {
        <p>Loading...</p>
        return;
    }

    <div class="avatar-preview">
        <img src="@editDisplayName" alt="Avatar" style="display:none;" />
        <div class="avatar-placeholder">
            <span>👤</span>
        </div>
        <p class="avatar-url">@editAvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="editDisplayName" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="editEmail" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" rows="4" @bind="editBio"></textarea>
    </div>

    <div class="form-group">
        <label for="avatarUrl">Avatar URL</label>
        <input id="avatarUrl" type="url" @bind="editAvatarUrl" />
    </div>

    <div class="button-group">
        <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (!string.IsNullOrEmpty(successMessage))
    {
        <div class="toast success">@successMessage</div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private UserProfile? profile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editBio = "";
    private string editAvatarUrl = "";
    private bool isSaving;
    private string? successMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && profile != Profile)
        {
            profile = Profile;
            ResetFields();
        }
    }

    private void ResetFields()
    {
        if (profile is null) return;
        editDisplayName = profile.DisplayName;
        editEmail = profile.Email;
        editBio = profile.Bio;
        editAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        successMessage = null;
        var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
        await OnSave.InvokeAsync(updated);
        profile = updated;
        isSaving = false;
        successMessage = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void Discard()
    {
        ResetFields();
        successMessage = null;
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_97d11cedc5ff4667abf60161c0fe1b08.Components.Pages.Settings
@using sv_97d11cedc5ff4667abf60161c0fe1b08.Services

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (Prefs is null)
    {
        <p>Loading...</p>
        return;
    }

    <div class="toggle-group">
        <label class="toggle-row">
            <span>Email Notifications</span>
            <input type="checkbox" @bind="emailNotifications" />
        </label>

        <label class="toggle-row">
            <span>Push Notifications</span>
            <input type="checkbox" @bind="pushNotifications" />
        </label>

        <label class="toggle-row">
            <span>Weekly Digest</span>
            <input type="checkbox" @bind="weeklyDigest" />
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in allChannels)
        {
            <label class="channel-row">
                <input type="checkbox"
                       checked="@mutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="button-group">
        <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save Preferences")
        </button>
    </div>

    @if (!string.IsNullOrEmpty(successMessage))
    {
        <div class="toast success">@successMessage</div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool isSaving;
    private string? successMessage;

    private static readonly string[] allChannels = ["general", "announcements", "updates", "marketing", "support"];

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        successMessage = null;
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Preferences saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_97d11cedc5ff4667abf60161c0fe1b08.Components.Pages.Settings
@using sv_97d11cedc5ff4667abf60161c0fe1b08.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (Settings is null)
    {
        <p>Loading...</p>
        return;
    }

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(passwordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPwd">Current Password</label>
                    <input id="currentPwd" type="password" @bind="currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPwd">New Password</label>
                    <input id="newPwd" type="password" @bind="newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPwd">Confirm Password</label>
                    <input id="confirmPwd" type="password" @bind="confirmPassword" />
                </div>

                @if (!string.IsNullOrEmpty(passwordError))
                {
                    <div class="toast error">@passwordError</div>
                }
                @if (!string.IsNullOrEmpty(passwordSuccess))
                {
                    <div class="toast success">@passwordSuccess</div>
                }

                <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@isChangingPassword">
                    @(isChangingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <span class="status-indicator @(Settings.TwoFactorEnabled ? "enabled" : "disabled")">
                @(Settings.TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
            </span>
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <p class="last-changed">Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("MMM dd, yyyy HH:mm")</td>
                        <td>
                            @if (session != Settings.Sessions.FirstOrDefault())
                            {
                                <button class="btn-danger btn-small"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-session">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Confirm Session Revocation</h4>
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="button-group">
                    <button class="btn-danger" @onclick="ConfirmRevokeAsync">Revoke Session</button>
                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private string? passwordSuccess;
    private bool isChangingPassword;
    private ActiveSession? sessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        isChangingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            passwordSuccess = "Password updated successfully!";
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
