<div class="settings-section">
    <h2>Security Settings</h2>

    @if (Settings is null)
    {
        <p>Loading...</p>
        return;
    }

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(passwordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPwd">Current Password</label>
                    <input id="currentPwd" type="password" @bind="currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPwd">New Password</label>
                    <input id="newPwd" type="password" @bind="newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPwd">Confirm Password</label>
                    <input id="confirmPwd" type="password" @bind="confirmPassword" />
                </div>

                @if (!string.IsNullOrEmpty(passwordError))
                {
                    <div class="toast error">@passwordError</div>
                }
                @if (!string.IsNullOrEmpty(passwordSuccess))
                {
                    <div class="toast success">@passwordSuccess</div>
                }

                <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@isChangingPassword">
                    @(isChangingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <span class="status-indicator @(Settings.TwoFactorEnabled ? "enabled" : "disabled")">
                @(Settings.TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
            </span>
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <p class="last-changed">Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("MMM dd, yyyy HH:mm")</td>
                        <td>
                            @if (session != Settings.Sessions.FirstOrDefault())
                            {
                                <button class="btn-danger btn-small"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-session">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Confirm Session Revocation</h4>
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="button-group">
                    <button class="btn-danger" @onclick="ConfirmRevokeAsync">Revoke Session</button>
                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private string? passwordSuccess;
    private bool isChangingPassword;
    private ActiveSession? sessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        isChangingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            passwordSuccess = "Password updated successfully!";
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
        finally
        {
            isChangingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }
}

