@namespace sv_97d11cedc5ff4667abf60161c0fe1b08.Components.Pages.Settings
@using sv_97d11cedc5ff4667abf60161c0fe1b08.Services

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (Settings is null)
    {
        <p>Loading...</p>
        return;
    }

    <!-- Theme Selector -->
    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-option">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(selectedTheme == theme)"
                           @onchange="() => selectedTheme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-option">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(selectedFontSize == size)"
                           @onchange="() => selectedFontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="selectedLanguage">
            <option value="en">English</option>
            <option value="es">Spanish</option>
            <option value="fr">French</option>
            <option value="de">German</option>
            <option value="ja">Japanese</option>
            <option value="zh">Chinese</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <label class="toggle-row">
        <span>Compact Mode</span>
        <input type="checkbox" @bind="compactMode" />
    </label>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Here is some example text to demonstrate the appearance.</p>
            <button class="btn-primary">Sample Button</button>
        </div>
    </div>

    <div class="button-group">
        <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save")
        </button>
    </div>

    @if (!string.IsNullOrEmpty(successMessage))
    {
        <div class="toast success">@successMessage</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "System";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;
    private bool isSaving;
    private string? successMessage;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{selectedTheme.ToLowerInvariant()} font-{selectedFontSize.ToLowerInvariant()}";
        if (compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        successMessage = null;
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Appearance saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

