+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+    color: #333;
+}
+
+.panel-header:hover {
+    background: #f0f0f0;
+}
+
+.panel-body {
+    padding: 1rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+/* TFA Section */
+.tfa-section {
+    margin-bottom: 1.5rem;
+}
+
+.status-indicator {
+    display: inline-block;
+    padding: 0.3rem 0.75rem;
+    border-radius: 12px;
+    font-size: 0.85rem;
+    font-weight: 500;
+}
+
+.status-indicator.enabled {
+    background: #e8f5e9;
+    color: #2e7d32;
+}
+
+.status-indicator.disabled {
+    background: #ffebee;
+    color: #c62828;
+}
+
+.last-changed {
+    font-size: 0.85rem;
+    color: #777;
+    margin-top: 0.5rem;
+}
+
+/* Sessions Table */
+.sessions-section {
+    margin-top: 1.5rem;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    color: #555;
+}
+
+.current-session {
+    font-size: 0.8rem;
+    color: #777;
+    font-style: italic;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+    margin-top: 0.25rem;
+}
+
+.radio-option {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Live Preview */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.25rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    transition: all 0.3s;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+    margin-bottom: 0.5rem;
+}
+
+.preview-card {
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 4px;
+    margin-top: 0.75rem;
+}
+
+/* Preview theme variants */
+.preview-area.theme-dark {
+    background: #263238;
+    color: #eceff1;
+    border-color: #455a64;
+}
+
+.preview-area.theme-dark .preview-card {
+    background: #37474f;
+}
+
+.preview-area.theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+.preview-area.theme-system {
+    background: #fafafa;
+    color: #333;
+}
+
+/* Preview font sizes */
+.preview-area.font-small {
+    font-size: 0.8rem;
+}
+
+.preview-area.font-medium {
+    font-size: 1rem;
+}
+
+.preview-area.font-large {
+    font-size: 1.2rem;
+}
+
+/* Preview compact */
+.preview-area.compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.preview-area.compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.5rem;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal-dialog {
+    background: white;
+    padding: 1.5rem;
+    border-radius: 8px;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.2);
+}
+
+.modal-dialog h4 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+}
+
+.modal-dialog p {
+    margin-bottom: 1.25rem;
+    color: #555;
+}
+

